package com.poultry.pms.entity;

import com.poultry.pms.entity.converter.InstantStringConverter;
import jakarta.persistence.Column;
import jakarta.persistence.Convert;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Table;

import java.time.Instant;

/**
 * A notification generated by this prototype's own rules (high mortality, low feed stock).
 * It is only stored and shown in the app: no SMS or email is sent.
 */
@Entity
@Table(name = "alert")
public class Alert extends BaseEntity {

    @Enumerated(EnumType.STRING)
    @Column(name = "alert_type", nullable = false)
    private AlertType alertType;

    @Enumerated(EnumType.STRING)
    @Column(name = "severity", nullable = false)
    private AlertSeverity severity;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private AlertStatus status = AlertStatus.OPEN;

    @Column(name = "message", nullable = false)
    private String message;

    @Column(name = "related_entity_type")
    private String relatedEntityType;

    @Column(name = "related_entity_id")
    private Long relatedEntityId;

    /** Identifies "the same problem" so we update one open alert instead of creating duplicates. */
    @Column(name = "dedup_key")
    private String dedupKey;

    @Convert(converter = InstantStringConverter.class)
    @Column(name = "resolved_at")
    private Instant resolvedAt;

    protected Alert() { }

    public Alert(AlertType alertType, AlertSeverity severity, String message,
                 String relatedEntityType, Long relatedEntityId, String dedupKey) {
        this.alertType = alertType;
        this.severity = severity;
        this.message = message;
        this.relatedEntityType = relatedEntityType;
        this.relatedEntityId = relatedEntityId;
        this.dedupKey = dedupKey;
    }

    public AlertType getAlertType() { return alertType; }
    public AlertSeverity getSeverity() { return severity; }
    public void setSeverity(AlertSeverity severity) { this.severity = severity; }
    public AlertStatus getStatus() { return status; }
    public void setStatus(AlertStatus status) { this.status = status; }
    public String getMessage() { return message; }
    public void setMessage(String message) { this.message = message; }
    public String getRelatedEntityType() { return relatedEntityType; }
    public Long getRelatedEntityId() { return relatedEntityId; }
    public String getDedupKey() { return dedupKey; }
    public Instant getResolvedAt() { return resolvedAt; }
    public void setResolvedAt(Instant resolvedAt) { this.resolvedAt = resolvedAt; }
}
